steps.solution:
function countSpaces(text) {
  // start a counter at 0
  let count = 0
  // loop over the string, one character at a time
  for (let i = 0; i < text.length; i++) {
    //   if the character is a space, add 1 to the counter
    if (text[i] === ' ') count++
  }
  // return the counter
  return count
}
